from pathlib import Path
import json,hashlib,sys
root=Path(__file__).resolve().parent
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
name=sys.argv[1] if len(sys.argv)>1 else 'portrait_v2'
status=sys.argv[2] if len(sys.argv)>2 else 'revised_candidate_ready_for_independent_qa'
e=json.loads((root/'sources/roster_entry.json').read_text());m=json.loads((root/'qa'/f'{name}_metrics.json').read_text());versions=[p.stem for p in sorted((root/'tool_returns').glob('portrait_v*.json'))]
raw=[]
for v in versions:
 metric=json.loads((root/'qa'/f'{v}_metrics.json').read_text());raw.append({'version':v,'raw_path':metric['raw']['path'],'raw_sha256':metric['raw']['sha256'],'tool_return_path':f'tool_returns/{v}.json','tool_return_sha256':metric['tool_return_sha256'],'raw_equals_decoded_tool_return':metric['raw_equals_decoded_tool_return'],'raw_dimensions':metric['raw']['size']})
manifest={'schema_version':1,'actor_id':e['canonical_id'],'name':e['name'],'slug':root.name,'date':'2026-10-15','selected_portrait':m['target']['path'],'selected_sha256':m['target']['sha256'],'status':status,'generation_calls_completed':len(versions),'generation_call_budget':2,'native_authored':False,'native_pixel_approved':False,'runtime_integrated':False,'runtime_verified':False,'old_assets_preserved':True,'method':'Built-in imagegen substantive redraw; one draft and one focused revision. Entire raw nearest-neighbor aspect-preserving fit within 72x98, centered on 74x100, binary alpha and no-dither temporary <=32 work-color quantization. No scripted character geometry or restoration. This is a derived export, not native pixel authorship.','selected_export':m['derivation'],'selected_target_metrics':m['target'],'raw_provenance':raw,'source_manifest':'sources/source_manifest.json','identity_lock':'spec_lock.md','exact_generation_arguments':[f'prompts/{v}.json' for v in versions],'tool':'image_gen.imagegen built-in','model_size_quality_seed':'Not exposed by built-in tool; no fabricated values.','independent_qa':'../independent_qa/batch14/FINAL_SELECTION.json','independent_technical_audit':'../independent_qa/batch14/technical_audit.json','independent_final_feedback':'qa/independent_final_feedback.json' if (root/'qa/independent_final_feedback.json').exists() else None,'reproduction':['python derive_portrait.py','python audit_artifacts.py',f'python finalize_manifest.py {name} {status}'],'reproduction_audit':'qa/reproducibility_and_source_integrity.json','previews':{'1x':m['target']['path'],'8x':f'previews/{name}_8x.png','1x_on_three_backgrounds_plus_8x':f'previews/{name}_1x_8x.png'},'limitations':['Imagegen pixel-style original is not natively authored 74x100 pixel art.','Temporary <=32 work-color ceiling is technical, not production palette approval.','Nearest-neighbor containment preserves sampled raw; it cannot restore raw-clipped or ungenerated details.','No old asset, card, gameplay code or runtime package changed. No commit or push.'],'self_visual_qa':'qa/self_visual_review.json','hash_inventory_rule':'manifest.files excludes manifest.json and SHA256SUMS.txt to avoid self-reference; SHA256SUMS.txt includes manifest.json and every other deliverable except itself.'}
manifest['files']=[{'path':str(p.relative_to(root)),'sha256':sha(p),'bytes':p.stat().st_size} for p in sorted(root.rglob('*')) if p.is_file() and p.name not in {'manifest.json','SHA256SUMS.txt'}]
(root/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n')
(root/'SHA256SUMS.txt').write_text(''.join(f'{sha(p)}  {p.relative_to(root)}\n' for p in sorted(root.rglob('*')) if p.is_file() and p.name!='SHA256SUMS.txt'))
print(json.dumps({'slug':root.name,'selected':manifest['selected_portrait'],'sha256':manifest['selected_sha256'],'files':len(manifest['files']),'status':status}))
